@classmethod
def _get_top_level_paths(cls, repo: "Repo") -> list["str"]:
    # Always include dvc.lock if it exists
    dvc_files = []
    dvc_lock_path = os.path.join(repo.root_dir, "dvc.lock")
    if os.path.exists(dvc_lock_path):
        dvc_files.append("dvc.lock")

    # Add other important top-level files if they exist
    important_files = ["metrics.json", "params.yaml", "plots.csv"]
    for file in important_files:
        if os.path.exists(os.path.join(repo.root_dir, file)):
            dvc_files.append(file)

    # Check for any untracked DVC-related files in the root directory
    scm = repo.scm
    if hasattr(scm, "untracked_files"):
        untracked = scm.untracked_files()
        for file in untracked:
            # Only include files in the root directory
            if os.path.dirname(file) == "":
                # Include DVC-related files and other important files
                if (file.endswith(".dvc") or 
                    file == "dvc.lock" or 
                    file in important_files):
                    if file not in dvc_files:
                        dvc_files.append(file)

    return list(
        chain(
            dvc_files,
            _collect_top_level_metrics(repo),
            _collect_top_level_params(repo),
            repo.index._plot_sources,
        )
    )
